"""Rewrite docs/space-budget.md from the fit model."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from mechanical.card_mech import stack as S          # noqa: E402
from mechanical.card_mech.checks import full_report  # noqa: E402

rep = full_report()
o = ["# Space budget", "",
     "Generated by `tools/space_budget.py` from the model in `mechanical/`. Lengths in millimetres.",
     "Part sizes come from `parts/parts.yaml`; several are still unverified there, and the cells",
     "are trade size codes with estimated capacities, not a supplier's drawing.", "",
     "## Rules the model applies", "",
     "- Nothing lies on the cell. The board is a strip along one long edge, the cell takes the rest,",
     f"  and a rib of the frame {S.RIB} wide runs between them.",
     "- Through the board, from the phone outwards: back skin, gap, parts, board, adhesive, front skin.",
     "  Every part is on the face of the board towards the phone. The other face lies under the front",
     "  skin and carries only the four contact pads.",
     "- Through the cell: back skin, adhesive, cell, gap, front skin.",
     f"- Cell: {S.SWELL:.0%} thickness growth allowed for; {S.CELL_GAP} around it; {S.CELL_TABS} beyond its body for the tabs.",
     "- The microphones are bottom-port parts: their sound comes through the board from the front.",
     f"  They are at least {S.MIN_MIC_DISTANCE:.0f} apart.",
     "- Every part the card decides has a place on the board and none overlaps another or a keep-out (antenna",
     f"  corner, light window, microphone gaskets). The two QFN chips keep {S.FINE_PITCH_MARGIN} clear.",
     f"- The other parts are counted here by area, each with {S.PART_SPACING} of spacing, and may take at most {S.PACKING:.0%} of the",
     "  free board. Their actual places are in the board file; nothing here checks that the tracks can be routed.",
     "- Nothing here checks stiffness: whether the two skins keep a bent card from bending the cell.", ""]
for key, e in rep["envelopes"].items():
    adopted = " (adopted)" if key == rep["adopted"] else ""
    o += [f"## Envelope {e['envelope']}{adopted}: {e['card'][0]} x {e['card'][1]} x {e['card'][2]}", "",
          f"**Result: {'everything fits' if e['ok'] else 'does not fit: ' + '; '.join(e['problems'])}.**", "",
          "| Through the board | Thickness | Through the cell | Thickness |", "| --- | --- | --- | --- |"]
    b, c = list(e["board_stack"].items()), list(e["cell_stack"].items())
    for i in range(max(len(b), len(c))):
        left = b[i] if i < len(b) else ("", "")
        right = c[i] if i < len(c) else ("", "")
        o.append(f"| {left[0]} | {left[1]} | {right[0]} | {right[1]} |")
    c, r, a, m = e["cell"], e["cell_room"], e["area"], e["mass"]
    o += ["", f"- **Room for the cell**: {r['length']} x {r['width']} x {r['thickness']} (thickness before swelling)."]
    if c:
        o += [f"- **Cell**: {c['mpn']}, {c['size'][0]} x {c['size'][1]} x {c['size'][2]}, about {c['capacity_mah']} mAh. "
              f"Spare: {c['spare_length']} in length, {c['spare_width']} in width, {c['spare_height']} in height."]
    o += [f"- **Board**: {e['board'][0]} x {e['board'][1]}, {a['board']} mm2. Large parts and keep-outs take {a['large_parts_and_keepouts']}; "
          f"the {a['small_parts']} small parts need {a['small_parts_need']}, {a['share_of_free']:.0%} of what is free.",
          f"- **Microphones**: {e['mic_distance']} apart.",
          f"- **Mass** (estimate): aluminium back skin {m['back_skin_g']} g, glass-filled plastic frame and front {m['frame_and_front_g']} g, "
          f"board {m['board_g']} g, cell {m['cell_g']} g: about {m['total_g']} g.",
          f"- Drawings: [from the phone side](../mechanical/out/plan-{key}.svg), [section](../mechanical/out/section-{key}.svg).", ""]
o += ["## What thickness and board width buy", "",
      "A payment card's outline. The cell is the best in `parts/parts.yaml` that fits; the table does not",
      "check that the parts fit under the back skin, which is what stops the 3.0 mm card above: its button is 1.35 tall.", "",
      "| Card thickness | Board width | Room for the cell | Best cell | Capacity |", "| --- | --- | --- | --- | --- |"]
for row in rep["size_sweep"]:
    r = row["room"]
    o.append(f"| {row['height']} | {row['board_w']} | {r['length']} x {r['width']} x {r['thickness']} | "
             f"{row['best_cell'] or 'none'} | {str(row['capacity_mah']) + ' mAh' if row['best_cell'] else ''} |")
o += ["", "The plan is fixed by the card, so thickness is the only free size: each half millimetre of cell is",
      "about 110 mAh at this length and width.", ""]
(ROOT / "docs" / "space-budget.md").write_text("\n".join(o))
print("docs/space-budget.md written")
